/**
 * TodoMVC (vanilla JS). The executable tier drives this through the real DOM that
 * features/support/world.js loads; no build step, no framework. Behaviour is split into
 * small seams, each carrying @planks(...) that name the Gherkin step patterns it serves.
 */
(function () {
  'use strict';

  const STORAGE_KEY = 'todos-vanilla';
  const FILTER_KEY = 'todos-vanilla-filter';
  const ENTER_KEY = 13;
  const ESCAPE_KEY = 27;

  var todos = [];
  var filter = 'all';

  function $(sel) { return document.querySelector(sel); }
  function $all(sel) { return Array.prototype.slice.call(document.querySelectorAll(sel)); }

  function genId() {
    return 't' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  /**
   * Read todos and the persisted active filter from localStorage.
   * @planks("the app is reloaded")
   */
  function load() {
    todos = [];
    filter = 'all';
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) todos = JSON.parse(raw);
    } catch (e) {
      todos = [];
    }
    if (!Array.isArray(todos)) todos = [];
    var f = localStorage.getItem(FILTER_KEY);
    if (f === 'active' || f === 'completed' || f === 'all') filter = f;
  }

  /**
   * Persist todos and the active filter, and shape the durable localStorage record.
   * @planks("localStorage holds a todo record for {string}")
   * @planks("localStorage has the key {string}")
   * @planks("^the persisted record for \"(.*)\" has the keys (.*)$")
   * @planks("the persisted record for {string} has {string} equal to {string}")
   */
  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    localStorage.setItem(FILTER_KEY, filter);
  }

  function parseRoute(hash) {
    if (!hash) return 'all';
    if (hash.indexOf('#/active') === 0) return 'active';
    if (hash.indexOf('#/completed') === 0) return 'completed';
    return 'all';
  }

  function routeHref(f) {
    if (f === 'active') return '#/active';
    if (f === 'completed') return '#/completed';
    return '#/';
  }

  function isVisible(todo) {
    if (filter === 'active') return !todo.completed;
    if (filter === 'completed') return todo.completed;
    return true;
  }

  function renderItem(todo) {
    var li = document.createElement('li');
    li.dataset.id = todo.id;
    if (todo.completed) li.classList.add('completed');

    var view = document.createElement('div');
    view.className = 'view';

    var toggle = document.createElement('input');
    toggle.className = 'toggle';
    toggle.type = 'checkbox';
    toggle.checked = todo.completed;

    var label = document.createElement('label');
    label.textContent = todo.title;

    var destroy = document.createElement('button');
    destroy.className = 'destroy';

    view.appendChild(toggle);
    view.appendChild(label);
    view.appendChild(destroy);

    var edit = document.createElement('input');
    edit.className = 'edit';
    edit.value = todo.title;

    li.appendChild(view);
    li.appendChild(edit);
    return li;
  }

  /**
   * Render the list, the main/footer visibility, the counter, the clear-completed button,
   * the mark-all checkbox and the selected filter link from current state.
   * @planks("the todo list shows the todo {string}")
   * @planks("the todo list shows the todos {string} and {string}")
   * @planks("the todo list shows only the todo {string}")
   * @planks("the todo list is empty")
   * @planks("the main section is not visible")
   * @planks("the footer section is not visible")
   * @planks("the clear completed button is not visible")
   * @planks("the clear completed button is visible")
   * @planks("the todo {string} is marked completed")
   * @planks("the todo {string} is not marked completed")
   * @planks("every todo is marked completed")
   * @planks("every todo is not marked completed")
   * @planks("the mark all as complete checkbox is checked")
   * @planks("the mark all as complete checkbox is unchecked")
   * @planks("the counter's strong element contains {string}")
   * @planks("the counter shows {string} left")
   * @planks("the {string} filter link is selected")
   * @planks("the todo {string} is not in editing mode")
   */
  function render() {
    var list = $('.todo-list');
    list.innerHTML = '';
    todos.forEach(function (todo) {
      if (isVisible(todo)) list.appendChild(renderItem(todo));
    });

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.length - activeCount;

    $('.main').hidden = todos.length === 0;
    $('.footer').hidden = todos.length === 0;
    $('.clear-completed').hidden = completedCount === 0;
    $('.todo-count').innerHTML =
      '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';
    $('#toggle-all').checked = todos.length > 0 && activeCount === 0;

    $all('.filters a').forEach(function (a) {
      a.classList.toggle('selected', a.getAttribute('href') === routeHref(filter));
    });
  }

  /**
   * Create a todo from the new-todo input and clear the input.
   * @planks("the user types {string} into the new todo input and presses Enter")
   * @planks("the new todo input is empty")
   * @planks("the app has the todo {string}")
   * @planks("the app has {int} active todos")
   */
  function addTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return;
    todos.push({ id: genId(), title: trimmed, completed: false });
    save();
    render();
  }

  /**
   * Toggle one todo's completed state.
   * @planks("the user checks the todo {string}")
   * @planks("the user unchecks the todo {string}")
   * @planks("the app has the completed todo {string}")
   */
  function toggle(id, completed) {
    todos.forEach(function (t) {
      if (t.id === id) t.completed = completed;
    });
    save();
    render();
  }

  /**
   * Toggle every todo to the same state as the mark-all checkbox.
   * @planks("the user checks the mark all as complete checkbox")
   * @planks("the user unchecks the mark all as complete checkbox")
   */
  function toggleAll(completed) {
    todos.forEach(function (t) { t.completed = completed; });
    save();
    render();
  }

  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
    render();
  }

  /**
   * Remove every completed todo.
   * @planks("the user clicks clear completed")
   */
  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
    render();
  }

  /**
   * Commit an in-place edit: trim, destroy the todo if emptied, otherwise rename it.
   * @planks("the user changes the edit input to {string} and presses Enter")
   * @planks("the user changes the edit input to {string} and blurs the input")
   */
  function commitEdit(id, title) {
    var trimmed = title.trim();
    if (!trimmed) {
      removeTodo(id);
      return;
    }
    todos.forEach(function (t) {
      if (t.id === id) t.title = trimmed;
    });
    save();
    render();
  }

  /**
   * Enter editing mode on double-click of a label, and wire the per-edit blur save.
   * @planks("the user double-clicks the label of the todo {string}")
   * @planks("the todo {string} is in editing mode")
   */
  function enterEditing(li) {
    li.classList.add('editing');
    var edit = li.querySelector('.edit');
    edit.focus();
    edit.value = edit.value;
    edit.addEventListener('blur', function () {
      commitEdit(li.dataset.id, edit.value);
    });
  }

  /**
   * Initialise: wire events, focus the new-todo input, load state and render.
   * @planks("the new todo input is focused")
   */
  function init() {
    load();

    var newTodo = $('.new-todo');
    newTodo.addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY || e.key === 'Enter') {
        addTodo(newTodo.value);
        newTodo.value = '';
      }
    });

    var list = $('.todo-list');
    list.addEventListener('change', function (e) {
      if (e.target.classList.contains('toggle')) {
        var li = e.target.closest('li');
        toggle(li.dataset.id, e.target.checked);
      }
    });
    list.addEventListener('dblclick', function (e) {
      if (e.target.tagName === 'LABEL') {
        enterEditing(e.target.closest('li'));
      }
    });
    list.addEventListener('keydown', function (e) {
      if (e.target.classList.contains('edit')) {
        var li = e.target.closest('li');
        if (e.keyCode === ENTER_KEY || e.key === 'Enter') {
          commitEdit(li.dataset.id, e.target.value);
        } else if (e.keyCode === ESCAPE_KEY || e.key === 'Escape') {
          render();
        }
      }
    });

    $('#toggle-all').addEventListener('change', function (e) {
      toggleAll(e.target.checked);
    });
    $('.clear-completed').addEventListener('click', clearCompleted);

    window.addEventListener('hashchange', function () {
      filter = parseRoute(window.location.hash);
      save();
      render();
    });

    newTodo.focus();
    render();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

const { Given, When, Then } = require('@cucumber/cucumber');

// ---- helpers ----------------------------------------------------------------

function todoLis(world) {
  return Array.prototype.slice.call(world.document.querySelectorAll('.todo-list li'));
}
function todoLi(world, title) {
  return todoLis(world).filter(function (li) {
    var label = li.querySelector('label');
    return label && label.textContent === title;
  })[0];
}
function storedTodos(window) {
  var raw = window.localStorage.getItem('todos-vanilla');
  if (!raw) return [];
  try { return JSON.parse(raw); } catch (e) { return []; }
}
function storedRecord(window, title) {
  return storedTodos(window).filter(function (t) { return t.title === title; })[0];
}
var seedSeq = 0;
function setStoredTodo(window, title, completed) {
  var arr = storedTodos(window);
  arr.push({ id: 'seed-' + (seedSeq++), title: title, completed: completed });
  window.localStorage.setItem('todos-vanilla', JSON.stringify(arr));
}

function addTodoViaUI(world, title) {
  var input = world.document.querySelector('.new-todo');
  input.value = title;
