#!/usr/bin/env node
/**
 * plank-join: cross-reference @planks / @planks-provisional annotations in the production
 * seam (js/) against the step-definition patterns in features/support/, and report which
 * scenarios bind each plank.
 *
 * Rules applied (per the Planking agreement):
 *  - Every @planks string must equal, exactly, a current step-definition pattern. A miss is a
 *    stale or malformed plank.
 *  - Every @planks-provisional reference must name a scenario that still carries @captain.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');

function read(p) { return fs.readFileSync(p, 'utf8'); }

function listFiles(dir, ext) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter((f) => f.endsWith(ext))
    .map((f) => path.join(dir, f));
}

// ---- collect planks from production ----------------------------------------

function collectPlanks() {
  const planks = []; // { file, line, kind: 'planks'|'provisional', value }
  const files = listFiles(path.join(ROOT, 'js'), '.js');
  files.forEach((file) => {
    const lines = read(file).split('\n');
    lines.forEach((line, i) => {
      const re = /@(planks|planks-provisional)\(\s*"((?:[^"\\]|\\.)*)"\s*\)/g;
      let m;
      while ((m = re.exec(line)) !== null) {
        planks.push({ file, line: i + 1, kind: m[1], value: m[2].replace(/\\"/g, '"') });
      }
    });
  });
  return planks;
}

// ---- collect step-definition patterns --------------------------------------

function collectStepDefs() {
  const stringPatterns = [];
  const regexPatterns = [];
  const files = listFiles(path.join(ROOT, 'features', 'support'), '.js');
  files.forEach((file) => {
    const src = read(file);
    // Given(...) / When(...) / Then(...) with a string or regex first argument.
    const re = /(?:Given|When|Then)\(\s*(\/|['"])/g;
    let m;
    while ((m = re.exec(src)) !== null) {
      if (m[1] === '/') {
        const end = src.indexOf('/', m.index + m[0].length);
        if (end !== -1) regexPatterns.push(src.slice(m.index + m[0].length, end));
      } else {
        const q = m[1];
        const start = m.index + m[0].length;
        const end = src.indexOf(q, start);
        if (end !== -1) stringPatterns.push(src.slice(start, end));
      }
    }
  });
  return { stringPatterns, regexPatterns };
}

// ---- collect scenarios from features ---------------------------------------

function collectScenarios() {
  const scenarios = []; // { file, name, steps: [], captain: bool }
  const files = listFiles(path.join(ROOT, 'features'), '.feature');
  files.forEach((file) => {
    const rel = path.relative(ROOT, file);
    const lines = read(file).split('\n');
    let current = null;
    let pendingTags = [];
    lines.forEach((raw) => {
      const line = raw.trim();
      const tagMatch = line.match(/^@(\w+)/);
      if (tagMatch) {
        pendingTags.push(tagMatch[1]);
        return;
      }
      const scenMatch = line.match(/^(Scenario|Scenario Outline):\s*(.*)$/);
      if (scenMatch) {
        if (current) scenarios.push(current);
        current = {
          file: rel,
          name: scenMatch[2].trim(),
          captain: pendingTags.indexOf('captain') !== -1,
          steps: [],
        };
        pendingTags = [];
        return;
      }
      if (/^(Given|When|Then|And|But)\s/.test(line)) {
        const text = line.replace(/^(Given|When|Then|And|But)\s/, '').trim();
        if (current) current.steps.push(text);
      }
    });
    if (current) scenarios.push(current);
  });
  return scenarios;
}

// ---- matching helpers ------------------------------------------------------

function ceMatcher(pattern) {
  let out = '';
  for (let i = 0; i < pattern.length; i++) {
    if (pattern.substr(i, 8) === '{string}') { out += '.*?'; i += 7; continue; }
    if (pattern.substr(i, 5) === '{int}') { out += '.*?'; i += 4; continue; }
    const c = pattern[i];
    if ('\\^$.*+?()[]{}|'.indexOf(c) !== -1) out += '\\' + c;
    else out += c;
  }
  return new RegExp('^' + out + '$');
}

function normStep(s) { return s.replace(/<[^>]*>/g, '.*?'); }

function matcherFor(plank, stepDefs) {
  if (stepDefs.stringPatterns.indexOf(plank) !== -1) return ceMatcher(plank);
  if (stepDefs.regexPatterns.indexOf(plank) !== -1) {
    try { return new RegExp(plank); } catch (e) { return null; }
  }
  return null;
}

// ---- main ------------------------------------------------------------------

const planks = collectPlanks();
const stepDefs = collectStepDefs();
const scenarios = collectScenarios();

let problems = 0;

console.log('Plank join\n=========');
console.log('Production planks found: ' + planks.length);

planks.forEach((p) => {
  const ref = p.file + ':' + p.line;
  if (p.kind === 'provisional') {
    // must name a @captain scenario
    const target = p.value; // features/x.feature:Scenario Name
    const [f, n] = [target.split(':')[0], target.split(':').slice(1).join(':')];
    const scen = scenarios.find((s) => s.file === f && s.name === n);
    if (!scen) {
      console.log('UNBOUND provisional ' + ref + ' -> "' + p.value + '" (scenario not found)');
      problems++;
    } else if (!scen.captain) {
      console.log('STALE provisional ' + ref + ' -> "' + p.value + '" (scenario no longer @captain)');
      problems++;
    } else {
      console.log('provisional ' + ref + ' -> ' + p.value + ' [captain]');
    }
    return;
  }

  const joined = stepDefs.stringPatterns.indexOf(p.value) !== -1 ||
    stepDefs.regexPatterns.indexOf(p.value) !== -1;
  if (!joined) {
    console.log('MALFORMED plank ' + ref + ' -> "' + p.value + '" (no matching step-definition pattern)');
    problems++;
    return;
  }
  const matcher = matcherFor(p.value, stepDefs);
  const bound = scenarios.filter((s) =>
    s.steps.some((st) => matcher && matcher.test(normStep(st))));
  console.log('plank ' + ref + ' -> "' + p.value + '" binds ' + bound.length + ' scenario(s)');
  bound.forEach((s) => console.log('    ' + s.file + ':' + s.name));
});

console.log('=========');
console.log(problems === 0 ? 'All planks join. Deck clean.' : (problems + ' plank problem(s).'));
process.exit(problems === 0 ? 0 : 1);

