files('features/support','.js').forEach(f=>{const s=read(f);const re=/(?:Given|When|Then)\(\s*(\/|['"])/g;let m;while((m=re.exec(s))){if(m[1]==='/'){const e=s.indexOf('/',m.index+m[0].length);if(e!==-1)sdefs.push({kind:'re',p:s.slice(m.index+m[0].length,e)});}else{const q=m[1];const st=m.index+m[0].length;const e=s.indexOf(q,st);if(e!==-1)sdefs.push({kind:'str',p:s.slice(st,e).replace(/\\'/g,"'")});}}});
const steps=[];
files('features','.feature').forEach(f=>{read(f).split('\n').forEach(line=>{const t=line.trim();if(/^(Given|When|Then|And|But)\s/.test(t))steps.push(t.replace(/^(Given|When|Then|And|But)\s/,'').trim());});});
const norm=s=>s.replace(/<[^>]*>/g,'.*?');
function ceMatcher(p){let out='';for(let i=0;i<p.length;i++){if(p.substr(i,8)==='{string}'){out+='.*?';i+=7;continue;}if(p.substr(i,5)==='{int}'){out+='.*?';i+=4;continue;}const c=p[i];out+='\\^$.*+?()[]{}|'.indexOf(c)!==-1?'\\'+c:c;}return new RegExp('^'+out+'$');}
function matches(d){const re=d.kind==='re'?new RegExp(d.p):ceMatcher(d.p);return steps.some(st=>re.test(norm(st)));}
let orphans=0;
sdefs.forEach(d=>{if(!matches(d)){orphans++;console.log('ORPHAN step def: '+d.p);}});
console.log(orphans?('ORPHANED step defs: '+orphans):'No orphaned step definitions.');
